package in.schemesathi.documents;
import org.junit.jupiter.api.Test;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.InjectMocks;import org.mockito.Mock;import org.mockito.junit.jupiter.MockitoExtension;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class DocumentServiceTest {
 @Mock DocumentCatalogRepository catalog;@Mock CitizenDocumentChecklistRepository checklist;@InjectMocks DocumentService service;
 @Test void upsertCreatesChecklistOwnedByCitizen(){UUID user=UUID.randomUUID(),docId=UUID.randomUUID();DocumentCatalogItem doc=mock(DocumentCatalogItem.class);when(doc.getId()).thenReturn(docId);when(doc.isActive()).thenReturn(true);when(doc.getCode()).thenReturn("AADHAAR");when(doc.getTitle()).thenReturn("Aadhaar");when(doc.getCategory()).thenReturn("IDENTITY");when(catalog.findById(docId)).thenReturn(Optional.of(doc));when(checklist.findByUserIdAndDocumentId(user,docId)).thenReturn(Optional.empty());when(checklist.save(any())).thenAnswer(i->i.getArgument(0));var response=service.upsert(user,new DocumentDtos.UpsertRequest(docId,"READY","In my possession"));assertEquals("READY",response.status());assertEquals("AADHAAR",response.code());verify(checklist).save(any(CitizenDocumentChecklist.class));}
 @Test void inactiveCatalogDocumentCannotBeAdded(){UUID docId=UUID.randomUUID();DocumentCatalogItem doc=mock(DocumentCatalogItem.class);when(doc.isActive()).thenReturn(false);when(catalog.findById(docId)).thenReturn(Optional.of(doc));assertThrows(NoSuchElementException.class,()->service.upsert(UUID.randomUUID(),new DocumentDtos.UpsertRequest(docId,"READY",null)));verifyNoInteractions(checklist);}
}
